 * Part 7.1 — the go-live stock take. Physical stock already on the shelf is
 * brought into the ledger as OPENING_BALANCE rows (never as a goods receipt:
 * no supplier is owed for it), with the matching Dr Inventory / Cr Opening
 * balance equity journal so the ledger and the books agree from day one.
 *
 * The whole file is all-or-nothing: every row is validated first and a
 * single bad row posts nothing, so a half-loaded opening balance can never
 * exist. Batches arrive RELEASED because the stock is already in trade;
 * anything past its expiry date arrives EXPIRED so FEFO never offers it.
 */";s:61:"␀PHPStan\Dependency\ExportedNode\ExportedPhpDocNode␀namespace";s:22:"App\Services\Inventory";s:56:"␀PHPStan\Dependency\ExportedNode\ExportedPhpDocNode␀uses";a:10:{s:8:"auditlog";s:19:"App\Models\AuditLog";s:7:"product";s:18:"App\Models\Product";s:12:"productbatch";s:23:"App\Models\ProductBatch";s:12:"stockbalance";s:23:"App\Models\StockBalance";s:11:"stockledger";s:22:"App\Models\StockLedger";s:5:"store";s:16:"App\Models\Store";s:13:"journalposter";s:34:"App\Services\Finance\JournalPoster";s:6:"carbon";s:25:"Illuminate\Support\Carbon";s:2:"db";s:29:"Illuminate\Support\Facades\DB";s:3:"str";s:22:"Illuminate\Support\Str";}s:61:"␀PHPStan\Dependency\ExportedNode\ExportedPhpDocNode␀constUses";a:0:{}}s:59:"␀PHPStan\Dependency\ExportedNode\ExportedClassNode␀abstract";b:0;s:56:"␀PHPStan\Dependency\ExportedNode\ExportedClassNode␀final";b:0;s:58:"␀PHPStan\Dependency\ExportedNode\ExportedClassNode␀extends";N;s:61:"␀PHPStan\Dependency\ExportedNode\ExportedClassNode␀implements";a:0:{}s:61:"␀PHPStan\Dependency\ExportedNode\ExportedClassNode␀usedTraits";a:0:{}s:70:"␀PHPStan\Dependency\ExportedNode\ExportedClassNode␀traitUseAdaptations";a:0:{}s:61:"␀PHPStan\Dependency\ExportedNode\ExportedClassNode␀statements";a:3:{i:0;O:50:"PHPStan\Dependency\ExportedNode\ExportedMethodNode":11:{s:56:"␀PHPStan\Dependency\ExportedNode\ExportedMethodNode␀name";s:11:"__construct";s:58:"␀PHPStan\Dependency\ExportedNode\ExportedMethodNode␀phpDoc";N;s:57:"␀PHPStan\Dependency\ExportedNode\ExportedMethodNode␀byRef";b:0;s:58:"␀PHPStan\Dependency\ExportedNode\ExportedMethodNode␀public";b:1;s:59:"␀PHPStan\Dependency\ExportedNode\ExportedMethodNode␀private";b:0;s:60:"␀PHPStan\Dependency\ExportedNode\ExportedMethodNode␀abstract";b:0;s:57:"␀PHPStan\Dependency\ExportedNode\ExportedMethodNode␀final";b:0;s:58:"␀PHPStan\Dependency\ExportedNode\ExportedMethodNode␀static";b:0;s:62:"␀PHPStan\Dependency\ExportedNode\ExportedMethodNode␀returnType";N;s:62:"␀PHPStan\Dependency\ExportedNode\ExportedMethodNode␀pa